START TRANSACTION;

-- lock outstanding milestones for this booking
SELECT id, due, paid
FROM milestones
WHERE booking_id = ? AND paid < due
ORDER BY due_date
FOR UPDATE;

-- allocate the receipt oldest-first, then
COMMIT;

SELECT *
FROM (
  SELECT a.*, ROW_NUMBER() OVER (
    PARTITION BY a.lead_id ORDER BY a.created_at DESC
  ) AS rn
  FROM activities a
) t
WHERE t.rn = 1;
